try (ServerSocket server = new ServerSocket(9000)) {
    while (true) {
        Socket s = server.accept();
        Thread.ofPlatform().start(() -> echo(s));   // or Thread.ofVirtual()
    }
}

static void echo(Socket s) {
    byte[] buf = new byte[512];
    try (s) {
        int n;
        while ((n = s.getInputStream().read(buf)) > 0) {   // asleep here when idle
            s.getOutputStream().write(buf, 0, n);
        }
    } catch (IOException e) { /* client went away */ }
}

