val selector = Selector.open()                                    // epoll_create1
val server = ServerSocketChannel.open().bind(InetSocketAddress(9000))
server.configureBlocking(false)
server.register(selector, SelectionKey.OP_ACCEPT)                // epoll_ctl(ADD)
val buf = ByteBuffer.allocateDirect(4096)
while (true) {
    selector.select()                                            // epoll_pwait
    val keys = selector.selectedKeys().iterator()
    while (keys.hasNext()) {
        val key = keys.next()
        keys.remove()                                            // or it comes back next turn
        if (key.isAcceptable) {
            val c = server.accept()                              // accept
            c.configureBlocking(false)                           // fcntl(O_NONBLOCK)
            c.register(selector, SelectionKey.OP_READ)           // epoll_ctl(ADD)
        } else if (key.isReadable) {
            val c = key.channel() as SocketChannel
            buf.clear()
            if (c.read(buf) < 0) { key.cancel(); c.close(); continue }   // read; close
            buf.flip()
            while (buf.hasRemaining()) c.write(buf)              // write
        }
    }
}
